# owner: platform
"""Snap spans to a fixed step and label them for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide 60: {step}")

# ---
def round_minutes(minutes: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minutes + step // 2) // step * step

def _round_span(span: Span, step: int) -> Span:
    start = round_minutes(span.start, step)
    end = round_minutes(span.end, step)
    return Span(start, end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"

# ---
def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Label each span after snapping its ends to the step."""
    _check_step(step)
    rounded = (_round_span(span, step) for span in spans)
    return [_label(span) for span in rounded]
